MovementPotionConsumables:
static boolean use(L1PcInstance pc, L1ItemInstance item, int itemId) {
    switch (itemId) {
        case 40030, 40013, 7006, 40018, 40039, 40040, 41338, 41261, 41262, 41268, 41269, 41271, 41272, 41273, 41342, 30067, 140013, 140018, 30158, 875640293 -> { return GreenMovementPotionUse.use(pc, item, itemId); }
        case 40014, 140014, 41415, 30073, 40068, 140068, 210110, 30076, 712, 40031, 30075, 40733 -> { return BraveryMovementPotionUse.use(pc, item, itemId); }
        case 713, 210036, 30077 -> { return FruitMovementPotionUse.use(pc, item, itemId); }
        default -> { return false; }
    }
}

GreenMovementPotionUse:
    static boolean use(L1PcInstance pc, L1ItemInstance l1iteminstance, int itemId) {
        switch (itemId) {
case 40030:
			useGreenPotion(pc, itemId);
			pc.getInventory().removeItem(l1iteminstance, 1);
			break;

		case 40013:
		case 7006:
		case 40018:
		case 40039:
		case 40040:
		case 41338:
		case 41261:
		case 41262:
		case 41268:
		case 41269:
		case 41271:
		case 41272:
		case 41273:
		case 41342:
		case 30067:
		case 140013:
		case 140018:
		case 30158:
		case 875640293:
			/*
			 * 초록 물약, 강화 초록 물약, 와인, 위스키, 상아탑의 속도향상 물약 축복받은 포도주, 주먹밥,
			 * 닭꼬치구이, 조각 피자, 옥수수구이 뻥튀기,오뎅, 와플, 메두사의 피, 용사의 속도 향상 물약,
			 */
			useGreenPotion(pc, itemId);
			pc.getInventory().removeItem(l1iteminstance, 1);
			break;
            default: break;
        }
        return false;
    }

